// Server Component
export default async function Post({ id }) {
  const post = await getPost(id);

  return (
    <article>
      <h2>{post.title}</h2>
      <p>{post.content}</p>
    </article>
  );
}

query PostPage($id: ID!) {
  post(id: $id) {
    title
    content

    ... @defer {
      recommendations {
        id
        title
      }
    }
  }
}

query PostComments($id: ID!) {
  post(id: $id) {
    comments @stream(initialCount: 3) {
      id
      content
    }
  }
}

